BEGIN;
DO $$ DECLARE def TEXT;BEGIN SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conrelid='public."FinanceAccount"'::regclass AND conname='FinanceAccount_controlType_check';ALTER TABLE public."FinanceAccount" DROP CONSTRAINT "FinanceAccount_controlType_check";EXECUTE 'ALTER TABLE public."FinanceAccount" ADD CONSTRAINT "FinanceAccount_controlType_check" CHECK(('||substr(def,8,length(def)-8)||') OR "controlType"=''INVESTMENT_INCOME_RECEIVABLE'')';SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conrelid='public."FinanceAccount"'::regclass AND conname='FinanceAccount_control_type';ALTER TABLE public."FinanceAccount" DROP CONSTRAINT "FinanceAccount_control_type";EXECUTE 'ALTER TABLE public."FinanceAccount" ADD CONSTRAINT "FinanceAccount_control_type" CHECK(('||substr(def,8,length(def)-8)||') OR(type=''ASSET'' AND "controlType"=''INVESTMENT_INCOME_RECEIVABLE''))';END $$;

CREATE SEQUENCE finance_holding_number AS BIGINT MINVALUE 1 MAXVALUE 9999999999 NO CYCLE;
CREATE TABLE "FinanceInvestmentHolding"(id UUID PRIMARY KEY,number TEXT NOT NULL UNIQUE,name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),"partyId" UUID NOT NULL REFERENCES "FinanceParty" ON DELETE RESTRICT,"investmentType" TEXT NOT NULL CHECK(length(trim("investmentType")) BETWEEN 1 AND 60),"unitMode" TEXT NOT NULL CHECK("unitMode" IN('UNIT','AMOUNT')),classification TEXT NOT NULL CHECK(classification IN('CURRENT','NONCURRENT')),"policyStatus" TEXT NOT NULL CHECK("policyStatus" IN('PENDING','REVIEWED')),"measurementMode" TEXT NOT NULL CHECK("measurementMode" IN('COST','MANUAL_VALUATION')),"valuationTreatment" TEXT NOT NULL CHECK("valuationTreatment" IN('PROFIT_LOSS','EQUITY')),policy TEXT NOT NULL CHECK(length(trim(policy)) BETWEEN 3 AND 2000),evidence TEXT NOT NULL CHECK(length(trim(evidence)) BETWEEN 3 AND 1000),"investmentAccountId" UUID NOT NULL REFERENCES "FinanceAccount" ON DELETE RESTRICT,"gainAccountId" UUID REFERENCES "FinanceAccount" ON DELETE RESTRICT,"lossAccountId" UUID REFERENCES "FinanceAccount" ON DELETE RESTRICT,"feeAccountId" UUID REFERENCES "FinanceAccount" ON DELETE RESTRICT,"incomeAccountId" UUID REFERENCES "FinanceAccount" ON DELETE RESTRICT,"incomeControlAccountId" UUID REFERENCES "FinanceAccount" ON DELETE RESTRICT,"valuationOffsetAccountId" UUID REFERENCES "FinanceAccount" ON DELETE RESTRICT,"impairmentAccountId" UUID REFERENCES "FinanceAccount" ON DELETE RESTRICT,active BOOLEAN NOT NULL DEFAULT true,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),"usedAt" TIMESTAMPTZ,"createdById" UUID NOT NULL REFERENCES "Person" ON DELETE RESTRICT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "FinanceInvestmentLot"(id UUID PRIMARY KEY,"holdingId" UUID NOT NULL REFERENCES "FinanceInvestmentHolding" ON DELETE RESTRICT,"movementId" UUID NOT NULL UNIQUE REFERENCES "FinanceMovement" ON DELETE RESTRICT,"acquisitionDate" DATE NOT NULL,cost NUMERIC(20,2) NOT NULL CHECK(cost>0),units NUMERIC(20,6) CHECK(units>0));
CREATE INDEX "FinanceInvestmentLot_holdingId_acquisitionDate_idx" ON "FinanceInvestmentLot"("holdingId","acquisitionDate");
CREATE TABLE "FinanceInvestmentEvent"(id UUID PRIMARY KEY,"holdingId" UUID NOT NULL REFERENCES "FinanceInvestmentHolding" ON DELETE RESTRICT,"lotId" UUID NOT NULL REFERENCES "FinanceInvestmentLot" ON DELETE RESTRICT,"movementId" UUID NOT NULL REFERENCES "FinanceMovement" ON DELETE RESTRICT,"journalId" UUID NOT NULL REFERENCES "FinanceJournalEntry" ON DELETE RESTRICT,"effectiveDate" DATE NOT NULL,"costDelta" NUMERIC(20,2) NOT NULL,"carryingDelta" NUMERIC(20,2) NOT NULL,"unitsDelta" NUMERIC(20,6),UNIQUE("movementId","lotId"),CHECK("costDelta"<>0 OR "carryingDelta"<>0 OR coalesce("unitsDelta",0)<>0));
CREATE INDEX "FinanceInvestmentEvent_holdingId_effectiveDate_idx" ON "FinanceInvestmentEvent"("holdingId","effectiveDate");
CREATE INDEX "FinanceInvestmentEvent_lotId_effectiveDate_idx" ON "FinanceInvestmentEvent"("lotId","effectiveDate");
CREATE TRIGGER "FinanceInvestmentLot_immutable" BEFORE UPDATE OR DELETE ON "FinanceInvestmentLot" FOR EACH ROW EXECUTE FUNCTION encova_finance_audit_immutable();
CREATE TRIGGER "FinanceInvestmentEvent_immutable" BEFORE UPDATE OR DELETE ON "FinanceInvestmentEvent" FOR EACH ROW EXECUTE FUNCTION encova_finance_audit_immutable();
CREATE TRIGGER "FinanceInvestmentHolding_config" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceInvestmentHolding" FOR EACH STATEMENT EXECUTE FUNCTION encova_finance_config_lock();
ALTER TABLE "FinanceMovement" ADD COLUMN "holdingId" UUID REFERENCES "FinanceInvestmentHolding" ON DELETE RESTRICT,ADD COLUMN units NUMERIC(20,6) CHECK(units>0);
CREATE FUNCTION encova_finance_holding_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'FINANCE_HISTORY_IMMUTABLE' USING ERRCODE='P0001';END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.number,NEW."createdById",NEW."createdAt") IS DISTINCT FROM ROW(OLD.id,OLD.number,OLD."createdById",OLD."createdAt") OR(NEW.version<>OLD.version+1 AND(to_jsonb(NEW)-ARRAY['usedAt','updatedAt']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['usedAt','updatedAt'])) THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF OLD."usedAt" IS NOT NULL AND(to_jsonb(NEW)-ARRAY['name','active','version','updatedAt']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['name','active','version','updatedAt']) THEN RAISE EXCEPTION 'FINANCE_HOLDING_TERMS_USED' USING ERRCODE='P0001';END IF;
  IF NEW."usedAt" IS DISTINCT FROM OLD."usedAt" AND(OLD."usedAt" IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" WHERE "holdingId"=NEW.id)) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 END IF;
 IF NOT NEW.active AND EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" WHERE "holdingId"=NEW.id HAVING coalesce(sum("costDelta"),0)<>0 OR coalesce(sum("carryingDelta"),0)<>0 OR coalesce(sum("unitsDelta"),0)<>0) THEN RAISE EXCEPTION 'FINANCE_HOLDING_OUTSTANDING' USING ERRCODE='P0001';END IF;
 IF TG_OP='INSERT' OR OLD."usedAt" IS NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public."FinanceParty" WHERE id=NEW."partyId" AND active) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."investmentAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='INVESTMENT' AND "reportGroup"=CASE WHEN NEW.classification='CURRENT' THEN 'CURRENT_ASSETS' ELSE 'NONCURRENT_ASSETS' END) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_MAPPING' USING ERRCODE='P0001';END IF;
  IF NEW."policyStatus"='REVIEWED' AND(NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."gainAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type='OTHER_INCOME') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."lossAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type='OTHER_EXPENSE') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."feeAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type IN('DIRECT_COST','OPERATING_EXPENSE','OTHER_EXPENSE')) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."incomeAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type='OTHER_INCOME') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."incomeControlAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='INVESTMENT_INCOME_RECEIVABLE') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."impairmentAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type='OTHER_EXPENSE') OR(NEW."measurementMode"='MANUAL_VALUATION' AND NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."valuationOffsetAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type=CASE WHEN NEW."valuationTreatment"='EQUITY' THEN 'EQUITY' ELSE 'OTHER_INCOME' END))) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_POLICY' USING ERRCODE='P0001';END IF;
 END IF;RETURN NEW;END $$;
CREATE TRIGGER "FinanceInvestmentHolding_guard" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceInvestmentHolding" FOR EACH ROW EXECUTE FUNCTION encova_finance_holding_guard();
CREATE FUNCTION encova_finance_investment_expected(target UUID) RETURNS TABLE("holdingId" UUID,"lotId" UUID,"costDelta" NUMERIC,"carryingDelta" NUMERIC,"unitsDelta" NUMERIC) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT d."holdingId",l.id,d.amount,d.amount,d.units FROM public."FinanceMovement" d JOIN public."FinanceInvestmentLot" l ON l."movementId"=d.id WHERE d.id=target AND d.kind='INVESTMENT_ACQUISITION'
 UNION ALL SELECT v."holdingId",v."lotId",-v."costDelta",-v."carryingDelta",-v."unitsDelta" FROM public."FinanceMovement" d JOIN public."FinanceInvestmentEvent" v ON v."movementId"=d."reversalOfId" WHERE d.id=target AND d.kind='REVERSAL';
$$;
ALTER FUNCTION encova_finance_movement_lines(UUID) RENAME TO encova_finance_movement_lines_f22;
CREATE FUNCTION encova_finance_movement_lines(target UUID) RETURNS TABLE(sequence INTEGER,"accountId" UUID,description TEXT,debit NUMERIC,credit NUMERIC,"projectId" UUID,"partyId" UUID) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT * FROM public.encova_finance_movement_lines_f22(target)
 UNION ALL SELECT 1,h."investmentAccountId",d.description,d.amount,0::numeric,NULL::uuid,h."partyId" FROM public."FinanceMovement" d JOIN public."FinanceInvestmentHolding" h ON h.id=d."holdingId" WHERE d.id=target AND d.kind='INVESTMENT_ACQUISITION'
 UNION ALL SELECT 2,c."glAccountId",d.description,0::numeric,d.amount,NULL::uuid,h."partyId" FROM public."FinanceMovement" d JOIN public."FinanceInvestmentHolding" h ON h.id=d."holdingId" JOIN public."FinanceCashAccount" c ON c.id=d."fromCashId" WHERE d.id=target AND d.kind='INVESTMENT_ACQUISITION';
$$;
ALTER FUNCTION encova_finance_movement_validate(UUID) RENAME TO encova_finance_movement_validate_f22;
CREATE FUNCTION encova_finance_movement_validate(target UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;h public."FinanceInvestmentHolding"%ROWTYPE;BEGIN
 SELECT * INTO d FROM public."FinanceMovement" WHERE id=target FOR UPDATE;
 IF d.kind<>'INVESTMENT_ACQUISITION' THEN PERFORM public.encova_finance_movement_validate_f22(target);ELSE
  SELECT * INTO h FROM public."FinanceInvestmentHolding" WHERE id=d."holdingId" FOR UPDATE;
  IF d.state<>'DRAFT' OR h.id IS NULL OR NOT h.active OR d."partyId" IS DISTINCT FROM h."partyId" OR d."fromCashId" IS NULL OR d."toCashId" IS NOT NULL OR d."controlAccountId" IS NOT NULL OR d."counterAccountId" IS NOT NULL OR d."loanId" IS NOT NULL OR d."billId" IS NOT NULL OR d."projectId" IS NOT NULL OR((h."unitMode"='UNIT')<>(d.units IS NOT NULL)) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_MAPPING' USING ERRCODE='P0001';END IF;
  IF h."policyStatus"<>'REVIEWED' THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_POLICY' USING ERRCODE='P0001';END IF;
  IF NOT EXISTS(SELECT 1 FROM public."FinanceParty" WHERE id=h."partyId" AND active) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=h."investmentAccountId" AND active AND "isPosting" AND "controlType"='INVESTMENT' AND "reportGroup"=CASE WHEN h.classification='CURRENT' THEN 'CURRENT_ASSETS' ELSE 'NONCURRENT_ASSETS' END) OR NOT EXISTS(SELECT 1 FROM public."FinanceCashAccount" c JOIN public."FinanceAccount" a ON a.id=c."glAccountId" WHERE c.id=d."fromCashId" AND c.active AND a.active AND a."controlType"='CASH' AND a."isPosting") THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_MAPPING' USING ERRCODE='P0001';END IF;
 END IF;
 IF d.kind='REVERSAL' AND EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" WHERE "movementId"=d."reversalOfId") THEN
  IF EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" v JOIN public."FinanceInvestmentEvent" current_events ON current_events."lotId"=v."lotId" WHERE v."movementId"=d."reversalOfId" GROUP BY v."lotId",v."costDelta",v."carryingDelta",v."unitsDelta" HAVING coalesce(sum(current_events."costDelta"),0)<v."costDelta" OR coalesce(sum(current_events."carryingDelta"),0)<v."carryingDelta" OR coalesce(sum(current_events."unitsDelta"),0)<coalesce(v."unitsDelta",0)) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_CAPACITY' USING ERRCODE='P0001';END IF;
 END IF;
END $$;
ALTER FUNCTION encova_finance_movement_effects(UUID,UUID,UUID) RENAME TO encova_finance_movement_effects_f22;
CREATE FUNCTION encova_finance_movement_effects(actor UUID,target UUID,entry_id UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;BEGIN
 SELECT * INTO d FROM public."FinanceMovement" WHERE id=target;
 IF d.kind='INVESTMENT_ACQUISITION' THEN INSERT INTO public."FinanceInvestmentLot"(id,"holdingId","movementId","acquisitionDate",cost,units) VALUES(gen_random_uuid(),d."holdingId",d.id,d."postingDate",d.amount,d.units);END IF;
 INSERT INTO public."FinanceInvestmentEvent"(id,"holdingId","lotId","movementId","journalId","effectiveDate","costDelta","carryingDelta","unitsDelta") SELECT gen_random_uuid(),v."holdingId",v."lotId",target,entry_id,d."postingDate",v."costDelta",v."carryingDelta",v."unitsDelta" FROM public.encova_finance_investment_expected(target)v;
 UPDATE public."FinanceInvestmentHolding" SET "usedAt"=coalesce("usedAt",CURRENT_TIMESTAMP) WHERE id IN(SELECT "holdingId" FROM public.encova_finance_investment_expected(target));
 PERFORM public.encova_finance_movement_effects_f22(actor,target,entry_id);
END $$;
ALTER FUNCTION encova_finance_check_movement(UUID) RENAME TO encova_finance_check_movement_f22;
CREATE FUNCTION encova_finance_check_movement(target UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;j UUID;BEGIN
 IF target IS NULL THEN RETURN;END IF;PERFORM public.encova_finance_check_movement_f22(target);SELECT * INTO d FROM public."FinanceMovement" WHERE id=target;SELECT id INTO j FROM public."FinanceJournalEntry" WHERE "movementId"=target;
 IF d.state<>'POSTED' THEN IF EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" WHERE "movementId"=target) OR EXISTS(SELECT 1 FROM public."FinanceInvestmentLot" WHERE "movementId"=target) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;RETURN;END IF;
 IF(d.kind='INVESTMENT_ACQUISITION' AND((SELECT count(*) FROM public."FinanceInvestmentLot" WHERE "movementId"=target)<>1 OR NOT EXISTS(SELECT 1 FROM public."FinanceInvestmentLot" WHERE "movementId"=target AND "holdingId"=d."holdingId" AND "acquisitionDate"=d."postingDate" AND cost=d.amount AND units IS NOT DISTINCT FROM d.units))) OR(d.kind<>'INVESTMENT_ACQUISITION' AND EXISTS(SELECT 1 FROM public."FinanceInvestmentLot" WHERE "movementId"=target)) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 IF EXISTS((SELECT "holdingId","lotId","costDelta","carryingDelta","unitsDelta" FROM public."FinanceInvestmentEvent" WHERE "movementId"=target) EXCEPT(SELECT * FROM public.encova_finance_investment_expected(target))) OR EXISTS((SELECT * FROM public.encova_finance_investment_expected(target)) EXCEPT(SELECT "holdingId","lotId","costDelta","carryingDelta","unitsDelta" FROM public."FinanceInvestmentEvent" WHERE "movementId"=target)) OR EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" WHERE "movementId"=target AND("journalId"<>j OR "effectiveDate"<>d."postingDate")) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 IF EXISTS(SELECT 1 FROM(SELECT sum("costDelta") OVER(PARTITION BY "lotId" ORDER BY "effectiveDate" RANGE UNBOUNDED PRECEDING) cost,sum("carryingDelta") OVER(PARTITION BY "lotId" ORDER BY "effectiveDate" RANGE UNBOUNDED PRECEDING) carrying,sum("unitsDelta") OVER(PARTITION BY "lotId" ORDER BY "effectiveDate" RANGE UNBOUNDED PRECEDING) units FROM public."FinanceInvestmentEvent" WHERE "lotId" IN(SELECT "lotId" FROM public.encova_finance_investment_expected(target)))v WHERE cost<0 OR carrying<0 OR units<0) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_CAPACITY' USING ERRCODE='P0001';END IF;
END $$;
CREATE FUNCTION encova_finance_investment_event_check() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN PERFORM public.encova_finance_check_movement(NEW."movementId");RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER "FinanceInvestmentEvent_valid" AFTER INSERT ON "FinanceInvestmentEvent" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION encova_finance_investment_event_check();
CREATE CONSTRAINT TRIGGER "FinanceInvestmentLot_valid" AFTER INSERT ON "FinanceInvestmentLot" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION encova_finance_investment_event_check();
DO $$ DECLARE def TEXT;BEGIN SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conrelid='public."FinanceMovement"'::regclass AND conname='FinanceMovement_kind_check';ALTER TABLE public."FinanceMovement" DROP CONSTRAINT "FinanceMovement_kind_check";EXECUTE 'ALTER TABLE public."FinanceMovement" ADD CONSTRAINT "FinanceMovement_kind_check" CHECK(('||substr(def,8,length(def)-8)||') OR kind=''INVESTMENT_ACQUISITION'')';SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conrelid='public."FinanceMovement"'::regclass AND conname='FinanceMovement_source_shape';ALTER TABLE public."FinanceMovement" DROP CONSTRAINT "FinanceMovement_source_shape";EXECUTE 'ALTER TABLE public."FinanceMovement" ADD CONSTRAINT "FinanceMovement_source_shape" CHECK(('||substr(def,8,length(def)-8)||' AND(kind=''REVERSAL'' OR("holdingId" IS NULL AND units IS NULL))) OR(kind=''INVESTMENT_ACQUISITION'' AND "holdingId" IS NOT NULL AND "partyId" IS NOT NULL AND "controlAccountId" IS NULL AND "counterAccountId" IS NULL AND "loanId" IS NULL AND "billId" IS NULL AND "projectId" IS NULL AND "fromCashId" IS NOT NULL AND "toCashId" IS NULL AND "reversalOfId" IS NULL))';END $$;
CREATE OR REPLACE FUNCTION encova_finance_movement_command(actor UUID,provider TEXT,session_id TEXT,verified_at TIMESTAMPTZ,action TEXT,input JSONB,request_key TEXT,request_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE d public."FinanceMovement"%ROWTYPE;o public."FinanceMovement"%ROWTYPE;r public."FinanceLedgerReceipt"%ROWTYPE;reason TEXT;digest TEXT;operation_name TEXT;result JSONB;entry_id UUID;original_id UUID;original_version INTEGER;original_number TEXT;BEGIN
 IF action IS NULL OR action NOT IN('CREATE','UPDATE','POST','VOID','REVERSE') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR request_key IS NULL OR length(request_key) NOT BETWEEN 8 AND 128 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF verified_at IS NULL OR verified_at<CURRENT_TIMESTAMP-interval '5 minutes' OR verified_at>CURRENT_TIMESTAMP+interval '5 seconds' THEN RAISE EXCEPTION 'FINANCE_REAUTH_REQUIRED' USING ERRCODE='P0001';END IF;
 reason:=trim(input->>'reason');IF reason IS NULL OR length(reason) NOT BETWEEN 3 AND 500 OR input-(CASE WHEN action='CREATE' THEN ARRAY['kind','reference','documentDate','postingDate','description','evidence','approvalEvidence','currency','amount','fromCashId','toCashId','partyId','controlAccountId','counterAccountId','projectId','billId','loanId','holdingId','units','reason'] WHEN action='UPDATE' THEN ARRAY['id','expectedVersion','kind','reference','documentDate','postingDate','description','evidence','approvalEvidence','currency','amount','fromCashId','toCashId','partyId','controlAccountId','counterAccountId','projectId','billId','loanId','holdingId','units','reason'] WHEN action='REVERSE' THEN ARRAY['id','expectedVersion','postingDate','reason'] ELSE ARRAY['id','expectedVersion','reason'] END)<>'{}'::jsonb THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(987661);PERFORM public.encova_finance_lock_person(actor);
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT public.encova_finance_session_ok(actor,provider,session_id) OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 operation_name:='MOVEMENT_'||action;digest:=encode(sha256(convert_to(jsonb_strip_nulls(input)::text,'UTF8')),'hex');SELECT * INTO r FROM public."FinanceLedgerReceipt" WHERE "actorId"=actor AND operation=operation_name AND key=request_key;
 IF FOUND THEN IF r."requestHash"<>digest THEN RAISE EXCEPTION 'FINANCE_IDEMPOTENCY_CONFLICT' USING ERRCODE='P0001';END IF;RETURN r.result;END IF;
 PERFORM pg_advisory_xact_lock(629815);
 IF action<>'CREATE' THEN
  IF jsonb_typeof(input->'expectedVersion') IS DISTINCT FROM 'number' OR(input->>'expectedVersion')::integer<1 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT * INTO d FROM public."FinanceMovement" WHERE id=(input->>'id')::uuid FOR UPDATE;
  IF d.id IS NULL THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;
  IF d.version<>(input->>'expectedVersion')::integer THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF(action='REVERSE' AND d.state<>'POSTED') OR(action<>'REVERSE' AND d.state<>'DRAFT') THEN RAISE EXCEPTION 'FINANCE_MOVEMENT_IMMUTABLE' USING ERRCODE='P0001';END IF;
 END IF;
 IF action IN('CREATE','UPDATE') THEN
  IF input->>'kind' IS NULL OR input->>'kind' NOT IN('TRANSFER','CAPITAL_CONTRIBUTION','CAPITAL_RETURN','DISTRIBUTION','NONCASH_CAPITAL','FOUNDER_OUTLAY','FOUNDER_BILL_SETTLEMENT','FOUNDER_REIMBURSEMENT','LOAN_DISBURSEMENT','LOAN_REPAYMENT','LOAN_INTEREST_ACCRUAL','LOAN_INTEREST_SETTLEMENT','LOAN_PRINCIPAL_INCREASE','LOAN_PRINCIPAL_DECREASE','INVESTMENT_ACQUISITION') OR input->>'currency' IS DISTINCT FROM 'PKR' OR jsonb_typeof(input->'amount') IS DISTINCT FROM 'string' OR input->>'amount' !~ '^(0|[1-9][0-9]{0,17})([.][0-9]{1,2})?$' OR(input->>'amount')::numeric<=0 OR input->>'documentDate' IS NULL OR input->>'documentDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR input->>'postingDate' IS NULL OR input->>'postingDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF input->>'kind'='INVESTMENT_ACQUISITION' THEN input:=input||jsonb_build_object('partyId',(SELECT "partyId" FROM public."FinanceInvestmentHolding" WHERE id=(input->>'holdingId')::uuid));IF input->>'units' IS NOT NULL AND(jsonb_typeof(input->'units')<>'string' OR input->>'units' !~ '^(0|[1-9][0-9]{0,13})([.][0-9]{1,6})?$' OR(input->>'units')::numeric<=0) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;END IF;
  IF input->>'kind' LIKE 'LOAN_%'  THEN input:=input||jsonb_build_object('partyId',(SELECT "partyId" FROM public."FinanceLoan" WHERE id=(input->>'loanId')::uuid));END IF;
  IF input->>'kind'='TRANSFER'  AND(input->>'partyId' IS NOT NULL OR input->>'controlAccountId' IS NOT NULL OR input->>'counterAccountId' IS NOT NULL OR input->>'projectId' IS NOT NULL OR input->>'approvalEvidence' IS NOT NULL OR input->>'billId' IS NOT NULL) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF action='CREATE' THEN INSERT INTO public."FinanceMovement"(id,number,kind,reference,"documentDate","postingDate",description,evidence,"approvalEvidence",currency,amount,"fromCashId","toCashId","partyId","controlAccountId","counterAccountId","projectId","billId","loanId","holdingId",units,"createdById") VALUES(gen_random_uuid(),'MVT-'||lpad(nextval('public.finance_movement_number')::text,10,'0'),input->>'kind',input->>'reference',(input->>'documentDate')::date,(input->>'postingDate')::date,input->>'description',input->>'evidence',input->>'approvalEvidence','PKR',(input->>'amount')::numeric,(input->>'fromCashId')::uuid,(input->>'toCashId')::uuid,(input->>'partyId')::uuid,(input->>'controlAccountId')::uuid,(input->>'counterAccountId')::uuid,(input->>'projectId')::uuid,(input->>'billId')::uuid,(input->>'loanId')::uuid,(input->>'holdingId')::uuid,(input->>'units')::numeric,actor) RETURNING * INTO d;
  ELSE IF input->>'kind' IS DISTINCT FROM d.kind THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;UPDATE public."FinanceMovement" SET "holdingId"=(input->>'holdingId')::uuid,units=(input->>'units')::numeric,"loanId"=(input->>'loanId')::uuid,"partyId"=(input->>'partyId')::uuid,"controlAccountId"=(input->>'controlAccountId')::uuid,"counterAccountId"=(input->>'counterAccountId')::uuid,"projectId"=(input->>'projectId')::uuid,"billId"=(input->>'billId')::uuid,"approvalEvidence"=input->>'approvalEvidence',reference=input->>'reference',"documentDate"=(input->>'documentDate')::date,"postingDate"=(input->>'postingDate')::date,description=input->>'description',evidence=input->>'evidence',amount=(input->>'amount')::numeric,"fromCashId"=(input->>'fromCashId')::uuid,"toCashId"=(input->>'toCashId')::uuid,"updatedAt"=CURRENT_TIMESTAMP,version=version+1 WHERE id=d.id RETURNING * INTO d;END IF;
 ELSIF action='VOID' THEN UPDATE public."FinanceMovement" SET state='VOIDED',version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=d.id RETURNING * INTO d;
 ELSIF action='REVERSE' THEN
  IF d.kind='REVERSAL' OR input->>'postingDate' IS NULL OR input->>'postingDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR EXISTS(SELECT 1 FROM public."FinanceMovement" WHERE "reversalOfId"=d.id) THEN RAISE EXCEPTION 'FINANCE_REVERSAL_INVALID' USING ERRCODE='P0001';END IF;
  o:=d;original_id:=d.id;original_number:=d.number;original_version:=d.version;
  INSERT INTO public."FinanceMovement" SELECT x.* FROM jsonb_populate_record(NULL::public."FinanceMovement",to_jsonb(o)||jsonb_build_object('id',gen_random_uuid(),'number','MVT-'||lpad(nextval('public.finance_movement_number')::text,10,'0'),'kind','REVERSAL','reversalOfId',o.id,'documentDate',(input->>'postingDate')::date,'postingDate',(input->>'postingDate')::date,'state','DRAFT','version',1,'sourceSnapshot',NULL,'createdById',actor,'createdAt',CURRENT_TIMESTAMP,'updatedAt',CURRENT_TIMESTAMP,'evidence',reason)) x RETURNING * INTO d;
  entry_id:=public.encova_finance_emit_journal(actor,'MOVEMENT',d.id,d."postingDate",reason);SELECT * INTO d FROM public."FinanceMovement" WHERE id=d.id;
 ELSE entry_id:=public.encova_finance_emit_journal(actor,'MOVEMENT',d.id,d."postingDate",reason);SELECT * INTO d FROM public."FinanceMovement" WHERE id=d.id;END IF;
 result:=CASE WHEN action='REVERSE' THEN jsonb_build_object('id',original_id,'version',original_version,'number',original_number,'journalId',entry_id,'reversalId',d.id) ELSE jsonb_build_object('id',d.id,'version',d.version,'number',d.number,'journalId',entry_id) END;
 INSERT INTO public."FinanceLedgerReceipt"(id,"actorId",operation,key,"requestHash",result) VALUES(gen_random_uuid(),actor,operation_name,request_key,digest,result);
 INSERT INTO public."FinanceAuditEvent"(id,"actorId",action,"entityType","entityId",reason,data,"requestId") VALUES(gen_random_uuid(),actor,'FINANCE_'||operation_name,'FinanceMovement',coalesce(original_id,d.id),reason,jsonb_build_object('journalId',entry_id,'snapshot',to_jsonb(d)||jsonb_build_object('amount',d.amount::text)),request_id);RETURN result;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'FINANCE_DUPLICATE' USING ERRCODE='P0001';
 WHEN check_violation OR not_null_violation OR foreign_key_violation OR invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';
END $$;
ALTER FUNCTION encova_finance_movement_snapshot(UUID) RENAME TO encova_finance_movement_snapshot_f22;
CREATE FUNCTION encova_finance_movement_snapshot(target UUID) RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT public.encova_finance_movement_snapshot_f22(target)||CASE WHEN d.kind='INVESTMENT_ACQUISITION' THEN jsonb_build_object('holding',to_jsonb(h),'units',d.units::text) ELSE '{}'::jsonb END FROM public."FinanceMovement" d LEFT JOIN public."FinanceInvestmentHolding" h ON h.id=d."holdingId" WHERE d.id=target $$;
CREATE OR REPLACE FUNCTION encova_finance_holding_command(actor UUID,provider TEXT,session_id TEXT,verified_at TIMESTAMPTZ,action TEXT,input JSONB,request_key TEXT,request_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE item public."FinanceInvestmentHolding"%ROWTYPE;prior public."FinanceLedgerReceipt"%ROWTYPE;reason TEXT;digest TEXT;result JSONB;BEGIN
 IF action IS NULL OR action NOT IN('CREATE','UPDATE','ARCHIVE','REACTIVATE') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR request_key IS NULL OR length(request_key) NOT BETWEEN 8 AND 128 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF verified_at IS NULL OR verified_at<CURRENT_TIMESTAMP-interval '5 minutes' OR verified_at>CURRENT_TIMESTAMP+interval '5 seconds' THEN RAISE EXCEPTION 'FINANCE_REAUTH_REQUIRED' USING ERRCODE='P0001';END IF;
 reason:=trim(input->>'reason');IF reason IS NULL OR length(reason) NOT BETWEEN 3 AND 500 OR input-(CASE WHEN action='CREATE' THEN ARRAY['name','partyId','investmentType','unitMode','classification','policyStatus','measurementMode','valuationTreatment','policy','evidence','investmentAccountId','gainAccountId','lossAccountId','feeAccountId','incomeAccountId','incomeControlAccountId','valuationOffsetAccountId','impairmentAccountId','reason'] WHEN action='UPDATE' THEN ARRAY['id','expectedVersion','name','partyId','investmentType','unitMode','classification','policyStatus','measurementMode','valuationTreatment','policy','evidence','investmentAccountId','gainAccountId','lossAccountId','feeAccountId','incomeAccountId','incomeControlAccountId','valuationOffsetAccountId','impairmentAccountId','reason'] ELSE ARRAY['id','expectedVersion','reason'] END)<>'{}'::jsonb THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(987661);PERFORM public.encova_finance_lock_person(actor);
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT public.encova_finance_session_ok(actor,provider,session_id) OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 digest:=encode(sha256(convert_to(jsonb_strip_nulls(input)::text,'UTF8')),'hex');SELECT * INTO prior FROM public."FinanceLedgerReceipt" WHERE "actorId"=actor AND operation='HOLDING_'||action AND key=request_key;
 IF FOUND THEN IF prior."requestHash"<>digest THEN RAISE EXCEPTION 'FINANCE_IDEMPOTENCY_CONFLICT' USING ERRCODE='P0001';END IF;RETURN prior.result;END IF;
 PERFORM pg_advisory_xact_lock(629815);
 IF action<>'CREATE' THEN
  IF jsonb_typeof(input->'expectedVersion') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT * INTO item FROM public."FinanceInvestmentHolding" WHERE id=(input->>'id')::uuid FOR UPDATE;
  IF item.id IS NULL THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;
  IF item.version<>(input->>'expectedVersion')::integer THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
 END IF;
 IF action IN('CREATE','UPDATE') THEN
  IF action='CREATE' THEN
   INSERT INTO public."FinanceInvestmentHolding" SELECT x.* FROM jsonb_populate_record(NULL::public."FinanceInvestmentHolding",input||jsonb_build_object('id',gen_random_uuid(),'number','HLD-'||lpad(nextval('public.finance_holding_number')::text,10,'0'),'active',true,'version',1,'usedAt',NULL,'createdById',actor,'createdAt',CURRENT_TIMESTAMP,'updatedAt',CURRENT_TIMESTAMP))x RETURNING * INTO item;
  ELSE
   UPDATE public."FinanceInvestmentHolding" SET "name"=input->>'name',"partyId"=(input->>'partyId')::uuid,"investmentType"=input->>'investmentType',"unitMode"=input->>'unitMode',"classification"=input->>'classification',"policyStatus"=input->>'policyStatus',"measurementMode"=input->>'measurementMode',"valuationTreatment"=input->>'valuationTreatment',"policy"=input->>'policy',"evidence"=input->>'evidence',"investmentAccountId"=(input->>'investmentAccountId')::uuid,"gainAccountId"=(input->>'gainAccountId')::uuid,"lossAccountId"=(input->>'lossAccountId')::uuid,"feeAccountId"=(input->>'feeAccountId')::uuid,"incomeAccountId"=(input->>'incomeAccountId')::uuid,"incomeControlAccountId"=(input->>'incomeControlAccountId')::uuid,"valuationOffsetAccountId"=(input->>'valuationOffsetAccountId')::uuid,"impairmentAccountId"=(input->>'impairmentAccountId')::uuid,version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=item.id RETURNING * INTO item;
  END IF;
 ELSE UPDATE public."FinanceInvestmentHolding" SET active=(action='REACTIVATE'),version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=item.id RETURNING * INTO item;END IF;
 result:=jsonb_build_object('id',item.id,'number',item.number,'version',item.version);
 INSERT INTO public."FinanceLedgerReceipt"(id,"actorId",operation,key,"requestHash",result) VALUES(gen_random_uuid(),actor,'HOLDING_'||action,request_key,digest,result);
 INSERT INTO public."FinanceAuditEvent"(id,"actorId",action,"entityType","entityId",reason,data,"requestId") VALUES(gen_random_uuid(),actor,'FINANCE_HOLDING_'||action,'FinanceInvestmentHolding',item.id,reason,jsonb_build_object('snapshot',to_jsonb(item)),request_id);RETURN result;
 EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'FINANCE_DUPLICATE' USING ERRCODE='P0001';WHEN check_violation OR not_null_violation OR foreign_key_violation OR invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';
END $$;
DO $$ DECLARE item RECORD;role_name TEXT;t TEXT;BEGIN
 FOREACH t IN ARRAY ARRAY['FinanceInvestmentHolding','FinanceInvestmentLot','FinanceInvestmentEvent'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC',t);IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN EXECUTE format('GRANT SELECT ON public.%I TO encova_app',t);EXECUTE format('CREATE POLICY encova_server_read ON public.%I FOR SELECT TO encova_app USING(true)',t);END IF;END LOOP;
 FOR item IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND(proname LIKE 'encova_finance_holding_%' OR proname LIKE 'encova_finance_investment_%' OR proname LIKE 'encova_finance_movement_%' OR proname LIKE 'encova_finance_check_movement%') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',item.signature);FOREACH role_name IN ARRAY ARRAY['anon','authenticated','encova_app'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',item.signature,role_name);END IF;END LOOP;END LOOP;
 FOREACH t IN ARRAY ARRAY['FinanceInvestmentHolding','FinanceInvestmentLot','FinanceInvestmentEvent','FinanceLoan','FinanceLoanEvent','FinanceFundingEvent'] LOOP FOREACH role_name IN ARRAY ARRAY['anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON public.%I FROM %I',t,role_name);END IF;END LOOP;END LOOP;
 REVOKE ALL ON SEQUENCE public.finance_holding_number FROM PUBLIC;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN GRANT EXECUTE ON FUNCTION encova_finance_holding_command(UUID,TEXT,TEXT,TIMESTAMPTZ,TEXT,JSONB,TEXT,UUID),encova_finance_movement_command(UUID,TEXT,TEXT,TIMESTAMPTZ,TEXT,JSONB,TEXT,UUID) TO encova_app;END IF;
END $$;
COMMIT;
